export const animeList = [
  { id: 1, title: "Solo Leveling", japanese: "Ore dake Level Up na Ken", year: 2024, score: 8.7, episodes: 12, status: "จบแล้ว", genres: ["Action", "Fantasy"], type: "TV", description: "ในโลกที่มนุษย์ต้องต่อสู้กับเหล่ามอนสเตอร์ผ่านเกต ซองจินอู ฮันเตอร์ระดับ E ผู้ถูกขนานนามว่าอ่อนแอที่สุด กลับได้รับพลังพิเศษที่ทำให้เขาสามารถเลเวลอัปได้เพียงคนเดียว", image: "https://images.unsplash.com/photo-1578632767115-351597cf2477?w=900", banner: "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=1600" },
  { id: 2, title: "Jujutsu Kaisen", japanese: "呪術廻戦", year: 2023, score: 8.8, episodes: 23, status: "จบแล้ว", genres: ["Action", "Supernatural"], type: "TV", description: "อิตาโดริ ยูจิ นักเรียนมัธยมที่เข้าไปพัวพันกับโลกของคำสาป หลังจากกลืนวัตถุต้องสาปอันทรงพลังและกลายเป็นภาชนะของสุคุนะ", image: "https://images.unsplash.com/photo-1601850494422-3cf14624b0b3?w=900", banner: "https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=1600" },
  { id: 3, title: "Demon Slayer", japanese: "Kimetsu no Yaiba", year: 2019, score: 8.6, episodes: 26, status: "จบแล้ว", genres: ["Action", "Fantasy"], type: "TV", description: "ทันจิโร่เริ่มต้นการเดินทางเพื่อช่วยน้องสาวและแก้แค้นอสูรที่พรากครอบครัวของเขาไป", image: "https://images.unsplash.com/photo-1578662996442-48f60103fc96?w=900", banner: "https://images.unsplash.com/photo-1470252649378-9c29740c9fa8?w=1600" },
  { id: 4, title: "Frieren: Beyond Journey's End", japanese: "Sousou no Frieren", year: 2023, score: 9.3, episodes: 28, status: "จบแล้ว", genres: ["Adventure", "Drama"], type: "TV", description: "หลังจบการเดินทางปราบจอมมาร เอลฟ์ผู้มีชีวิตยืนยาวออกเดินทางครั้งใหม่เพื่อทำความเข้าใจความหมายของเวลาและความสัมพันธ์", image: "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=900", banner: "https://images.unsplash.com/photo-1448375240586-882707db888b?w=1600" },
  { id: 5, title: "Spy x Family", japanese: "スパイファミリー", year: 2022, score: 8.5, episodes: 25, status: "กำลังฉาย", genres: ["Comedy", "Action"], type: "TV", description: "สายลับ นักฆ่า และเด็กหญิงผู้มีพลังอ่านใจ ต้องมาใช้ชีวิตเป็นครอบครัวปลอม ๆ เพื่อภารกิจลับ", image: "https://images.unsplash.com/photo-1535016120720-40c646be5580?w=900", banner: "https://images.unsplash.com/photo-1500534623283-312aade485b7?w=1600" },
  { id: 6, title: "Your Name", japanese: "Kimi no Na wa", year: 2016, score: 8.9, episodes: 1, status: "จบแล้ว", genres: ["Romance", "Drama"], type: "Movie", description: "วัยรุ่นสองคนที่ไม่เคยพบกันกลับสลับร่างและเชื่อมโยงกันผ่านเหตุการณ์เหนือธรรมชาติ", image: "https://images.unsplash.com/photo-1470770841072-f978cf4d019e?w=900", banner: "https://images.unsplash.com/photo-1470770841072-f978cf4d019e?w=1600" },
  { id: 7, title: "Haikyuu!!", japanese: "ハイキュー!!", year: 2014, score: 8.7, episodes: 25, status: "จบแล้ว", genres: ["Sports", "Drama"], type: "TV", description: "ฮินาตะ เด็กหนุ่มตัวเล็กผู้หลงใหลวอลเลย์บอล มุ่งมั่นจะก้าวสู่สนามระดับประเทศ", image: "https://images.unsplash.com/photo-1519861531473-9200262188bf?w=900", banner: "https://images.unsplash.com/photo-1519861531473-9200262188bf?w=1600" },
  { id: 8, title: "Chainsaw Man", japanese: "チェンソーマン", year: 2022, score: 8.4, episodes: 12, status: "จบแล้ว", genres: ["Action", "Horror"], type: "TV", description: "เด็นจิ ชายหนุ่มผู้ใช้ชีวิตอย่างยากลำบาก ได้กลายเป็นมนุษย์เลื่อยยนต์และเข้าร่วมหน่วยล่าปีศาจ", image: "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=900", banner: "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=1600" }
];

